PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS restaurants(id INTEGER PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,logo_path TEXT NOT NULL DEFAULT '',currency TEXT NOT NULL DEFAULT 'MAD',tax_rate INTEGER NOT NULL DEFAULT 0,service_rate INTEGER NOT NULL DEFAULT 0,default_language TEXT NOT NULL DEFAULT 'fr',languages TEXT NOT NULL DEFAULT '["fr","en","ar","es","de","zh"]',order_mode TEXT NOT NULL DEFAULT 'table',subscription_plan TEXT NOT NULL DEFAULT 'Starter',subscription_status TEXT NOT NULL DEFAULT 'trial',subscription_end TEXT NOT NULL,accepting_orders INTEGER NOT NULL DEFAULT 0,google_review_url TEXT NOT NULL DEFAULT 'https://g.page/r/PLACEHOLDER/review',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('platform_admin','restaurant_admin','staff')),restaurant_id INTEGER REFERENCES restaurants(id),password_hash TEXT,active INTEGER NOT NULL DEFAULT 1,mfa_secret TEXT,mfa_counter INTEGER NOT NULL DEFAULT -1,session_version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,CHECK(role='platform_admin' OR restaurant_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS tokens(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),token_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,used_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS recovery_codes(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),code_hash TEXT NOT NULL UNIQUE,used_at INTEGER);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY,restaurant_id INTEGER NOT NULL REFERENCES restaurants(id),name_fr TEXT NOT NULL,name_en TEXT NOT NULL DEFAULT '',name_ar TEXT NOT NULL DEFAULT '',name_es TEXT NOT NULL DEFAULT '',name_de TEXT NOT NULL DEFAULT '',name_zh TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY,restaurant_id INTEGER NOT NULL REFERENCES restaurants(id),category_id INTEGER NOT NULL REFERENCES categories(id),name_fr TEXT NOT NULL,name_en TEXT NOT NULL DEFAULT '',name_ar TEXT NOT NULL DEFAULT '',name_es TEXT NOT NULL DEFAULT '',name_de TEXT NOT NULL DEFAULT '',name_zh TEXT NOT NULL DEFAULT '',description_fr TEXT NOT NULL DEFAULT '',description_en TEXT NOT NULL DEFAULT '',description_ar TEXT NOT NULL DEFAULT '',description_es TEXT NOT NULL DEFAULT '',description_de TEXT NOT NULL DEFAULT '',description_zh TEXT NOT NULL DEFAULT '',price INTEGER NOT NULL,image_path TEXT NOT NULL DEFAULT '',allergens TEXT NOT NULL DEFAULT '[]',available INTEGER NOT NULL DEFAULT 1,featured INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS dining_tables(id INTEGER PRIMARY KEY,restaurant_id INTEGER NOT NULL REFERENCES restaurants(id),label TEXT NOT NULL,seats INTEGER NOT NULL DEFAULT 2,zone TEXT NOT NULL DEFAULT '',access_token TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1,UNIQUE(restaurant_id,label));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,status_token TEXT NOT NULL UNIQUE,restaurant_id INTEGER NOT NULL REFERENCES restaurants(id),table_id INTEGER REFERENCES dining_tables(id),order_type TEXT NOT NULL CHECK(order_type IN('table','counter','takeaway')),guest_count INTEGER NOT NULL DEFAULT 1,customer_name TEXT NOT NULL DEFAULT '',customer_note TEXT NOT NULL DEFAULT '',allergies TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','confirmed','preparing','ready','served','cancelled')),payment_method TEXT NOT NULL CHECK(payment_method IN('table','counter','online')),payment_status TEXT NOT NULL DEFAULT 'pending' CHECK(payment_status IN('pending','paid','refunded','failed')),subtotal INTEGER NOT NULL,tax INTEGER NOT NULL,service INTEGER NOT NULL,total INTEGER NOT NULL,created_by INTEGER REFERENCES users(id),rating INTEGER,rating_comment TEXT NOT NULL DEFAULT '',rated_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),item_id INTEGER NOT NULL REFERENCES items(id),item_name TEXT NOT NULL,unit_price INTEGER NOT NULL,quantity INTEGER NOT NULL,guest_name TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',allergens TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS rate_limits(bucket TEXT PRIMARY KEY,hits INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),restaurant_id INTEGER REFERENCES restaurants(id),event TEXT NOT NULL,entity TEXT NOT NULL DEFAULT '',entity_id INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS service_requests(id INTEGER PRIMARY KEY,restaurant_id INTEGER NOT NULL REFERENCES restaurants(id),table_id INTEGER NOT NULL REFERENCES dining_tables(id),kind TEXT NOT NULL CHECK(kind IN('waiter','bill')),created_at INTEGER NOT NULL,resolved_at INTEGER,resolved_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS screens(id INTEGER PRIMARY KEY,restaurant_id INTEGER NOT NULL REFERENCES restaurants(id),name TEXT NOT NULL,pin TEXT UNIQUE,pin_expires_at INTEGER,token_hash TEXT UNIQUE,last_seen INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS signage_content(id INTEGER PRIMARY KEY,restaurant_id INTEGER NOT NULL REFERENCES restaurants(id),kind TEXT NOT NULL CHECK(kind IN('image','video')),path TEXT NOT NULL,title TEXT NOT NULL DEFAULT '',duration INTEGER NOT NULL DEFAULT 10,start_date TEXT,end_date TEXT,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,bytes INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS signage_targets(content_id INTEGER NOT NULL REFERENCES signage_content(id),screen_id INTEGER REFERENCES screens(id));
CREATE INDEX IF NOT EXISTS items_restaurant ON items(restaurant_id,category_id,sort_order);
CREATE INDEX IF NOT EXISTS orders_restaurant ON orders(restaurant_id,created_at);
CREATE INDEX IF NOT EXISTS order_items_order ON order_items(order_id);
CREATE INDEX IF NOT EXISTS audit_time ON audit(created_at);
CREATE INDEX IF NOT EXISTS service_requests_open ON service_requests(restaurant_id,resolved_at);
CREATE INDEX IF NOT EXISTS screens_restaurant ON screens(restaurant_id);
CREATE INDEX IF NOT EXISTS signage_restaurant ON signage_content(restaurant_id,sort_order);
CREATE INDEX IF NOT EXISTS signage_targets_content ON signage_targets(content_id);
